import { describe, expect, it } from "vitest";
import { attachControl, interpolateArcRotateCamera } from "@babylonjs/lite";

type Listener = (e: any) => void;

function makeCanvas() {
    const map = new Map<string, Listener[]>();
    return {
        addEventListener(ev: string, h: Listener) { map.set(ev, [...(map.get(ev) ?? []), h]); },
        removeEventListener(ev: string, h: Listener) { map.set(ev, (map.get(ev) ?? []).filter((x) => x !== h)); },
        setPointerCapture() {},
        releasePointerCapture() {},
        fire(ev: string, e: any) { for (const h of map.get(ev) ?? []) h(e); },
    };
}

function makeCamera(alpha: number, beta: number, radius: number) {
    return {
        alpha, beta, radius,
        target: { x: 0, y: 0, z: 0 },
        inertialAlphaOffset: 0, inertialBetaOffset: 0, inertialRadiusOffset: 0,
        inertialPanningX: 0, inertialPanningY: 0,
        angularSensibility: 1000, panningSensibility: 50, wheelPrecision: 3,
        inertia: 0.9, panningInertia: 0.9,
    } as any;
}

function tick(scene: any, n = 1) {
    for (let i = 0; i < n; i++) for (const cb of [...scene._beforeRender]) cb(16);
}

function track(p: Promise<void>) {
    const s = { state: "pending" as string, reason: "" };
    p.then(() => { s.state = "resolves"; }, (e) => { s.state = "rejects"; s.reason = String(e?.message ?? e); });
    return s;
}

describe("probe", () => {
    it("a: flick then goHome", async () => {
        const scene: any = { _beforeRender: [] };
        const canvas = makeCanvas();
        const camera = makeCamera(1.0, 1.2, 10);
        attachControl(camera, canvas as any, scene);
        canvas.fire("pointerdown", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 100, clientY: 100 });
        canvas.fire("pointermove", { pointerId: 1, clientX: 160, clientY: 100 });
        canvas.fire("pointerup", { pointerId: 1 });
        tick(scene, 0);
        const before = camera.inertialAlphaOffset;
        const r = track(interpolateArcRotateCamera(camera, scene, { alpha: 0, radius: 4 }));
        tick(scene, 3000);
        await new Promise((r2) => setTimeout(r2, 0));
        console.log("A inertia before goHome:", before, "state:", r.state, r.reason, "alpha", camera.alpha, "radius", camera.radius);
        expect(r.state).toBe("resolves");
    });

    it("b: drag mid-transition", async () => {
        const scene: any = { _beforeRender: [] };
        const canvas = makeCanvas();
        const camera = makeCamera(1.0, 1.2, 10);
        attachControl(camera, canvas as any, scene);
        const r = track(interpolateArcRotateCamera(camera, scene, { alpha: 0, radius: 4 }));
        tick(scene, 10);
        canvas.fire("pointerdown", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 100, clientY: 100 });
        canvas.fire("pointermove", { pointerId: 1, clientX: 130, clientY: 100 });
        tick(scene, 1);
        await new Promise((r2) => setTimeout(r2, 0));
        console.log("B state:", r.state, r.reason, "remaining hooks:", scene._beforeRender.length);
        expect(r.state).toBe("rejects");
    });

    it("c: second goHome mid-transition", async () => {
        const scene: any = { _beforeRender: [] };
        const canvas = makeCanvas();
        const camera = makeCamera(1.0, 1.2, 10);
        attachControl(camera, canvas as any, scene);
        const first = track(interpolateArcRotateCamera(camera, scene, { alpha: 0, radius: 4 }));
        tick(scene, 10);
        const second = track(interpolateArcRotateCamera(camera, scene, { alpha: 0, radius: 4 }));
        tick(scene, 3000);
        await new Promise((r2) => setTimeout(r2, 0));
        console.log("C first:", first.state, first.reason, "second:", second.state, second.reason);
        expect(first.state).toBe("rejects");
        expect(second.state).toBe("resolves");
    });
});
